using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(100, ErrorMessage = "Title must be 100 characters or fewer.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "Ingredients are required.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "Steps are required.")]
    public string Steps { get; set; } = string.Empty;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly Lock _lock = new();

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough
San Marzano tomatoes
Fresh mozzarella
Fresh basil
Olive oil
Salt", Steps = "1. Preheat oven to 475°F.
2. Roll out dough on floured surface.
3. Spread crushed tomatoes evenly.
4. Tear mozzarella and distribute.
5. Bake 10-12 minutes until crust is golden.
6. Top with fresh basil and drizzle olive oil.", AverageRating = 4.5, RatingCount = 12 },
            new() { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti
Guanciale or pancetta
Eggs
Pecorino Romano
Black pepper", Steps = "1. Cook spaghetti in salted water.
2. Crisp guanciale in a pan.
3. Whisk eggs with grated Pecorino and pepper.
4. Toss hot pasta with guanciale.
5. Remove from heat, stir in egg mixture.
6. Serve immediately with extra cheese.", AverageRating = 4.8, RatingCount = 20 },
            new() { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs
Yogurt
Garam masala
Turmeric
Cumin
Tomato sauce
Cream
Garlic
Ginger", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.
2. Grill or broil chicken until charred.
3. Sauté garlic and ginger in oil.
4. Add tomato sauce and spices, simmer 15 min.
5. Add cream and cooked chicken.
6. Simmer 10 minutes. Serve with rice.", AverageRating = 4.6, RatingCount = 15 },
            new() { Id = 4, Title = "Vegetable Pad Thai", Category = "Asian", Ingredients = "Rice noodles
Tofu
Bean sprouts
Green onions
Peanuts
Lime
Fish sauce
Tamarind paste
Sugar
Chili flakes", Steps = "1. Soak rice noodles in warm water 20 min.
2. Press and cube tofu, pan-fry until golden.
3. Mix tamarind, fish sauce, sugar for sauce.
4. Stir-fry noodles with sauce.
5. Add tofu and bean sprouts.
6. Serve with peanuts, lime, green onions.", AverageRating = 4.3, RatingCount = 8 },
            new() { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef
Taco seasoning
Corn tortillas
Lettuce
Tomato
Cheddar cheese
Sour cream
Salsa", Steps = "1. Brown ground beef in a skillet.
2. Add taco seasoning and water, simmer 5 min.
3. Warm tortillas in a dry pan.
4. Fill tortillas with beef.
5. Top with lettuce, tomato, cheese.
6. Serve with sour cream and salsa.", AverageRating = 4.2, RatingCount = 10 },
            new() { Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate
Butter
Eggs
Sugar
Flour
Vanilla extract", Steps = "1. Preheat oven to 425°F.
2. Melt chocolate and butter together.
3. Whisk eggs and sugar until thick.
4. Fold in chocolate mixture and flour.
5. Pour into greased ramekins.
6. Bake 12-14 min (center should be soft).
7. Invert onto plates, serve immediately.", AverageRating = 4.9, RatingCount = 25 },
            new() { Id = 7, Title = "Miso Ramen", Category = "Asian", Ingredients = "Ramen noodles
Miso paste
Chicken broth
Soy sauce
Sesame oil
Soft-boiled egg
Green onions
Nori
Corn", Steps = "1. Bring chicken broth to a boil.
2. Whisk in miso paste and soy sauce.
3. Cook ramen noodles separately.
4. Place noodles in bowls, ladle broth over.
5. Top with soft-boiled egg, corn, nori.
6. Drizzle sesame oil and add green onions.", AverageRating = 4.7, RatingCount = 18 },
            new() { Id = 8, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados
Lime juice
Cilantro
Red onion
Jalapeño
Tomato
Salt
Garlic", Steps = "1. Halve and pit avocados.
2. Mash avocado to desired consistency.
3. Dice onion, tomato, jalapeño, cilantro.
4. Mix everything together.
5. Add lime juice, garlic, and salt.
6. Serve with tortilla chips.", AverageRating = 4.4, RatingCount = 14 },
        };
    }

    public IReadOnlyList<string> GetCategories()
    {
        lock (_lock)
        {
            return _recipes.Select(r => r.Category).Distinct().Order().ToList();
        }
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        lock (_lock)
        {
            return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
        }
    }

    public Recipe? GetById(int id)
    {
        lock (_lock)
        {
            return _recipes.FirstOrDefault(r => r.Id == id);
        }
    }

    public void AddRating(int recipeId, int stars)
    {
        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
            if (recipe is null || stars < 1 || stars > 5) return;

            var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
            recipe.RatingCount++;
            recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
        }
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        lock (_lock)
        {
            var newId = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1;
            _recipes.Add(new Recipe
            {
                Id = newId,
                Title = submission.Title,
                Category = submission.Category,
                Ingredients = submission.Ingredients,
                Steps = submission.Steps
            });
        }
    }
}

