}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">
                            ⭐ @recipe.AverageRating / 5
                            <span class="text-muted">(@recipe.RatingCount ratings)</span>
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string Category { get; set; } = string.Empty;

    private IReadOnlyList<RecipeShare.Models.Recipe> recipes = [];

    protected override void OnInitialized()
    {
        recipes = RecipeService.GetByCategory(Category);
    }
}

@page "/recipe/{Id:int}"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

@if (recipe is null)
{
    <p>Recipe not found.</p>
    <a href="/">← Back to Home</a>
}
else
{
    <h1>@recipe.Title</h1>
    <p><a href="/recipes/@recipe.Category">← Back to @recipe.Category</a></p>

    <div class="row">
        <div class="col-md-8">
            <div class="card mb-3">
                <div class="card-header"><strong>Ingredients</strong></div>
                <div class="card-body">
                    <ul class="mb-0">
                        @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <li>@ingredient</li>
                        }
                    </ul>
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-header"><strong>Steps</strong></div>
                <div class="card-body">
                    @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p class="mb-1">@step</p>
                    }
                </div>
            </div>
        </div>

        <div class="col-md-4">
            <div class="card">
                <div class="card-header"><strong>Rating</strong></div>
                <div class="card-body">
                    <p>⭐ @recipe.AverageRating / 5 (@recipe.RatingCount ratings)</p>
                    <StarRating RecipeId="@recipe.Id" />
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeShare.Models.Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@inject RecipeShare.Services.RecipeService RecipeService

<div class="star-rating">
    <p class="mb-1">Rate this recipe:</p>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= hoveredStar ? "hovered" : "") @(submitted ? "disabled" : "")"
              @onmouseover="() => OnHover(star)"
              @onmouseout="OnHoverOut"
              @onclick="() => SubmitRating(star)"
              role="button">
            @(star <= hoveredStar ? "★" : "☆")
        </span>
    }
    @if (submitted)
    {
        <p class="text-success mt-2">Thanks! You rated this @submittedRating/5 stars.</p>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int hoveredStar;
    private int submittedRating;
    private bool submitted;

    private void OnHover(int star)
    {
        if (!submitted) hoveredStar = star;
    }

    private void OnHoverOut()
    {
        if (!submitted) hoveredStar = 0;
    }

    private void SubmitRating(int star)
    {
        if (submitted) return;
        RecipeService.AddRating(RecipeId, star);
        submittedRating = star;
        hoveredStar = star;
        submitted = true;
    }
}

.star-rating .star {
    font-size: 1.8rem;
    cursor: pointer;
    color: #ccc;
    transition: color 0.15s;
}

.star-rating .star.hovered {
    color: #f5a623;
}

.star-rating .star.disabled {
    cursor: default;
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeShare.Services.RecipeService RecipeService
@inject NavigationManager Navigation
@using RecipeShare.Models

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (successMessage is not null)
{
    <div class="alert alert-success">@successMessage</div>
}

<EditForm Model="submission" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="submission.Title" />
        <ValidationMessage For="() => submission.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="submission.Category">
            <option value="">-- Select a category --</option>
            <option value="Italian">Italian</option>
            <option value="Indian">Indian</option>
            <option value="Asian">Asian</option>
            <option value="Mexican">Mexican</option>
            <option value="Desserts">Desserts</option>
            <option value="Other">Other</option>
        </InputSelect>
        <ValidationMessage For="() => submission.Category" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="submission.Ingredients" />
        <ValidationMessage For="() => submission.Ingredients" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Preparation Steps (one per line)</label>
        <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="submission.Steps" />
        <ValidationMessage For="() => submission.Steps" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-success">Submit Recipe</button>
</EditForm>

@code {
    private RecipeSubmission submission = new();
    private string? successMessage;

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(submission);
        successMessage = $"'{submission.Title}' has been submitted successfully!";
        submission = new();
    }
}

